CREATE TABLE survey_report_controls(kind TEXT PRIMARY KEY CHECK(kind IN ('waste','inspection','palms')),submission_enabled INTEGER NOT NULL DEFAULT 1 CHECK(submission_enabled IN (0,1)),viewer_enabled INTEGER NOT NULL DEFAULT 1 CHECK(viewer_enabled IN (0,1)));
INSERT INTO survey_report_controls(kind) VALUES('waste'),('inspection'),('palms');
CREATE TRIGGER survey_controls_insert BEFORE INSERT ON survey_report_controls BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM write_guards g JOIN sessions s ON s.token_hash=g.token_hash JOIN users u ON u.id=s.user_id WHERE g.role='admin' AND u.dashboard='survey' AND u.role='admin' AND u.is_active=1 AND u.deleted_at IS NULL AND s.version=u.version AND s.expires_at>unixepoch()*1000) THEN RAISE(ABORT,'FORBIDDEN') END; END;
CREATE TRIGGER survey_controls_update BEFORE UPDATE ON survey_report_controls BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM write_guards g JOIN sessions s ON s.token_hash=g.token_hash JOIN users u ON u.id=s.user_id WHERE g.role='admin' AND u.dashboard='survey' AND u.role='admin' AND u.is_active=1 AND u.deleted_at IS NULL AND s.version=u.version AND s.expires_at>unixepoch()*1000) THEN RAISE(ABORT,'FORBIDDEN') END; END;
CREATE TRIGGER survey_controls_delete BEFORE DELETE ON survey_report_controls BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM write_guards g JOIN sessions s ON s.token_hash=g.token_hash JOIN users u ON u.id=s.user_id WHERE g.role='admin' AND u.dashboard='survey' AND u.role='admin' AND u.is_active=1 AND u.deleted_at IS NULL AND s.version=u.version AND s.expires_at>unixepoch()*1000) THEN RAISE(ABORT,'FORBIDDEN') END; END;
CREATE TRIGGER survey_submission_control BEFORE INSERT ON reports WHEN EXISTS(SELECT 1 FROM write_guards g JOIN sessions s ON s.token_hash=g.token_hash JOIN users u ON u.id=s.user_id WHERE u.role='supervisor') BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM survey_report_controls WHERE kind=NEW.kind AND submission_enabled=1) THEN RAISE(ABORT,'Report submissions are currently disabled by Admin.') END; END;
CREATE TABLE date_palm_reports(id TEXT PRIMARY KEY,number TEXT NOT NULL,supervisor_id TEXT NOT NULL REFERENCES users(id),site TEXT NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',latitude REAL NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude REAL NOT NULL CHECK(longitude BETWEEN -180 AND 180),gps_accuracy_meters REAL NOT NULL,gps_captured_at TEXT NOT NULL,location_id TEXT NOT NULL UNIQUE REFERENCES location_verifications(id),photo_ids TEXT NOT NULL CHECK(json_valid(photo_ids)),idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(strftime('%Y-%m-%dT%H:%M:%fZ','now')),deleted_at TEXT,UNIQUE(supervisor_id,idempotency_key));
INSERT INTO sequences(kind,value) VALUES('palms',0);
CREATE UNIQUE INDEX palms_active_number ON date_palm_reports(number) WHERE deleted_at IS NULL;
CREATE INDEX palms_owner ON date_palm_reports(supervisor_id,deleted_at);
CREATE TRIGGER palms_insert BEFORE INSERT ON date_palm_reports BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM write_guards g JOIN sessions s ON s.token_hash=g.token_hash JOIN users u ON u.id=s.user_id WHERE g.role IN ('submit','admin') AND u.id=NEW.supervisor_id AND u.dashboard='survey' AND u.role IN ('admin','supervisor') AND u.is_active=1 AND u.deleted_at IS NULL AND s.version=u.version AND s.expires_at>unixepoch()*1000 AND (u.role='admin' OR EXISTS(SELECT 1 FROM survey_report_controls WHERE kind='palms' AND submission_enabled=1))) THEN RAISE(ABORT,'FORBIDDEN') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM location_verifications l,app_settings a WHERE l.id=NEW.location_id AND l.user_id=NEW.supervisor_id AND l.used_at IS NULL AND l.viewed_at IS NOT NULL AND l.confirmed_at>=l.viewed_at AND julianday(l.captured_at) BETWEEN julianday('now','-5 minutes') AND julianday('now','+10 seconds') AND l.accuracy<=a.gps_accuracy_meters AND l.latitude=NEW.latitude AND l.longitude=NEW.longitude AND l.accuracy=NEW.gps_accuracy_meters AND l.captured_at=NEW.gps_captured_at) THEN RAISE(ABORT,'Capture and confirm a recent accurate GPS location.') END;
 SELECT CASE WHEN json_array_length(NEW.photo_ids) NOT BETWEEN 1 AND 3 OR (SELECT count(DISTINCT value) FROM json_each(NEW.photo_ids))<>json_array_length(NEW.photo_ids) OR (SELECT count(*) FROM photo_uploads WHERE id IN(SELECT value FROM json_each(NEW.photo_ids)) AND user_id=NEW.supervisor_id AND used_at IS NULL)<>json_array_length(NEW.photo_ids) THEN RAISE(ABORT,'Photographs must belong to you and be unused.') END;
END;
CREATE TRIGGER palms_update BEFORE UPDATE ON date_palm_reports BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM write_guards g JOIN sessions s ON s.token_hash=g.token_hash JOIN users u ON u.id=s.user_id WHERE g.role='admin' AND u.dashboard='survey' AND u.role='admin' AND u.is_active=1 AND u.deleted_at IS NULL AND s.version=u.version AND s.expires_at>unixepoch()*1000) OR NEW.id<>OLD.id OR NEW.supervisor_id<>OLD.supervisor_id OR NEW.photo_ids<>OLD.photo_ids OR NEW.location_id<>OLD.location_id OR NEW.idempotency_key<>OLD.idempotency_key OR NEW.created_at<>OLD.created_at THEN RAISE(ABORT,'FORBIDDEN') END;
END;
CREATE TRIGGER palms_delete BEFORE DELETE ON date_palm_reports BEGIN SELECT RAISE(ABORT,'Use audited soft deletion.'); END;
